package com.roadwatch.report; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; @Service class CivicNotifier { private final String webhook; CivicNotifier(@Value("${civic.webhook}")String webhook){this.webhook=webhook;} void notify(PotholeReport report){if(!webhook.isBlank())RestClient.create().post().uri(webhook).body(report).retrieve().toBodilessEntity();} }
